1051|static bufsize_t manual_scan_link_url_2(cmark_chunk *input, bufsize_t offset,
1052|                                        cmark_chunk *output) {
1053|  bufsize_t i = offset;
1054|  size_t nb_p = 0;
1055|
1056|  while (i < input->len) {
1057|    if (input->data[i] == '\\' &&
1058|        i + 1 < input-> len &&
1059|        cmark_ispunct(input->data[i+1]))
1060|      i += 2;
1061|    else if (input->data[i] == '(') {
1062|      ++nb_p;
1063|      ++i;
1064|      if (nb_p > 32)
1065|        return -1;
1066|    } else if (input->data[i] == ')') {
1067|      if (nb_p == 0)
1068|        break;
1069|      --nb_p;
1070|      ++i;
1071|    } else if (cmark_isspace(input->data[i])) {
1072|      if (i == offset) {
1073|        return -1;
1074|      }
1075|      break;
1076|    } else {
1077|      ++i;
1078|    }
1079|  }
1080|
1081|  if (i >= input->len || nb_p != 0)
1082|    return -1;
1083|
1084|  {
1085|    cmark_chunk result = {input->data + offset, i - offset};
