1091|static bufsize_t manual_scan_link_url(cmark_chunk *input, bufsize_t offset,
1092|                                      cmark_chunk *output) {
1093|  bufsize_t i = offset;
1094|
1095|  if (i < input->len && input->data[i] == '<') {
1096|    ++i;
1097|    while (i < input->len) {
1098|      if (input->data[i] == '>') {
1099|        ++i;
1100|        break;
1101|      } else if (input->data[i] == '\\')
1102|        i += 2;
1103|      else if (input->data[i] == '\n' || input->data[i] == '<')
1104|        return -1;
1105|      else
1106|        ++i;
1107|    }
1108|  } else {
1109|    return manual_scan_link_url_2(input, offset, output);
1110|  }
1111|
1112|  if (i >= input->len)
1113|    return -1;
1114|
1115|  {
1116|    cmark_chunk result = {input->data + offset + 1, i - 2 - offset};
1117|    *output = result;
1118|  }
1119|  return i - offset;
