1122|// Return a link, an image, or a literal close bracket.
1123|static cmark_node *handle_close_bracket(subject *subj) {
1124|  bufsize_t initial_pos, after_link_text_pos;
1125|  bufsize_t endurl, starttitle, endtitle, endall;
1126|  bufsize_t sps, n;
1127|  cmark_reference *ref = NULL;
1128|  cmark_chunk url_chunk, title_chunk;
1129|  unsigned char *url, *title;
1130|  bracket *opener;
1131|  cmark_node *inl;
1132|  cmark_chunk raw_label;
1133|  int found_label;
1134|  cmark_node *tmp, *tmpnext;
1135|  bool is_image;
1136|
1137|  advance(subj); // advance past ]
1138|  initial_pos = subj->pos;
1139|
1140|  // get last [ or ![
1141|  opener = subj->last_bracket;
1142|
1143|  if (opener == NULL) {
1144|    return make_str(subj, subj->pos - 1, subj->pos - 1, cmark_chunk_literal("]"));
1145|  }
1146|
1147|  // If we got here, we matched a potential link/image text.
1148|  // Now we check to see if it's a link/image.
1149|  is_image = opener->image;
1150|
1151|  if (!is_image && subj->no_link_openers) {
1152|    // take delimiter off stack
1153|    pop_bracket(subj);
1154|    return make_str(subj, subj->pos - 1, subj->pos - 1, cmark_chunk_literal("]"));
1155|  }
1156|
1157|  after_link_text_pos = subj->pos;
1158|
1159|  // First, look for an inline link.
1160|  if (peek_char(subj) == '(' &&
1161|      ((sps = scan_spacechars(&subj->input, subj->pos + 1)) > -1) &&
1162|      ((n = manual_scan_link_url(&subj->input, subj->pos + 1 + sps,
1163|                                 &url_chunk)) > -1)) {
1164|
1165|    // try to parse an explicit link:
1166|    endurl = subj->pos + 1 + sps + n;
1167|    starttitle = endurl + scan_spacechars(&subj->input, endurl);
1168|
1169|    // ensure there are spaces btw url and title
1170|    endtitle = (starttitle == endurl)
1171|                   ? starttitle
1172|                   : starttitle + scan_link_title(&subj->input, starttitle);
1173|
1174|    endall = endtitle + scan_spacechars(&subj->input, endtitle);
1175|
1176|    if (peek_at(subj, endall) == ')') {
1177|      subj->pos = endall + 1;
1178|
1179|      title_chunk =
1180|          cmark_chunk_dup(&subj->input, starttitle, endtitle - starttitle);
1181|      url = cmark_clean_url(subj->mem, &url_chunk);
1182|      title = cmark_clean_title(subj->mem, &title_chunk);
1183|      cmark_chunk_free(&url_chunk);
1184|      cmark_chunk_free(&title_chunk);
1185|      goto match;
1186|
1187|    } else {
1188|      // it could still be a shortcut reference link
1189|      subj->pos = after_link_text_pos;
1190|    }
1191|  }
1192|
1193|  // Next, look for a following [link label] that matches in refmap.
1194|  // skip spaces
1195|  raw_label = cmark_chunk_literal("");
1196|  found_label = link_label(subj, &raw_label);
1197|  if (!found_label) {
1198|    // If we have a shortcut reference link, back up
1199|    // to before the spaces we skipped.
1200|    subj->pos = initial_pos;
1201|  }
1202|
1203|  if ((!found_label || raw_label.len == 0) && !opener->bracket_after) {
1204|    cmark_chunk_free(&raw_label);
1205|    raw_label = cmark_chunk_dup(&subj->input, opener->position,
1206|                                initial_pos - opener->position - 1);
1207|    found_label = true;
1208|  }
1209|
1210|  if (found_label) {
1211|    ref = cmark_reference_lookup(subj->refmap, &raw_label);
1212|    cmark_chunk_free(&raw_label);
1213|  }
1214|
1215|  if (ref != NULL) { // found
1216|    url = cmark_strdup(subj->mem, ref->url);
1217|    title = cmark_strdup(subj->mem, ref->title);
1218|    goto match;
1219|  } else {
1220|    goto noMatch;
1221|  }
1222|
1223|noMatch:
1224|  // If we fall through to here, it means we didn't match a link:
1225|  pop_bracket(subj); // remove this opener from delimiter list
1226|  subj->pos = initial_pos;
1227|  return make_str(subj, subj->pos - 1, subj->pos - 1, cmark_chunk_literal("]"));
1228|
1229|match:
1230|  inl = make_simple(subj->mem, is_image ? CMARK_NODE_IMAGE : CMARK_NODE_LINK);
1231|  inl->as.link.url = url;
1232|  inl->as.link.title = title;
1233|  inl->start_line = inl->end_line = subj->line;
1234|  inl->start_column = opener->inl_text->start_column;
1235|  inl->end_column = subj->pos + subj->column_offset + subj->block_offset;
1236|  cmark_node_insert_before(opener->inl_text, inl);
1237|  // Add link text:
1238|  tmp = opener->inl_text->next;
1239|  while (tmp) {
1240|    tmpnext = tmp->next;
1241|    cmark_node_unlink(tmp);
1242|    append_child(inl, tmp);
1243|    tmp = tmpnext;
1244|  }
1245|
1246|  // Free the bracket [:
1247|  cmark_node_free(opener->inl_text);
