1262|// Parse a hard or soft linebreak, returning an inline.
1263|// Assumes the subject has a cr or newline at the current position.
1264|static cmark_node *handle_newline(subject *subj) {
1265|  bufsize_t nlpos = subj->pos;
1266|  // skip over cr, crlf, or lf:
1267|  if (peek_at(subj, subj->pos) == '\r') {
1268|    advance(subj);
1269|  }
1270|  if (peek_at(subj, subj->pos) == '\n') {
1271|    advance(subj);
1272|  }
1273|  ++subj->line;
1274|  subj->column_offset = -subj->pos;
1275|  // skip spaces at beginning of line
1276|  skip_spaces(subj);
1277|  if (nlpos > 1 && peek_at(subj, nlpos - 1) == ' ' &&
1278|      peek_at(subj, nlpos - 2) == ' ') {
1279|    return make_linebreak(subj->mem);
1280|  } else {
1281|    return make_softbreak(subj->mem);
1282|  }
