1328|// Parse an inline, advancing subject, and add it as a child of parent.
1329|// Return 0 if no inline can be parsed, 1 otherwise.
1330|static int parse_inline(subject *subj, cmark_node *parent, int options) {
1331|  cmark_node *new_inl = NULL;
1332|  cmark_chunk contents;
1333|  unsigned char c;
1334|  bufsize_t startpos, endpos;
1335|  c = peek_char(subj);
1336|  if (c == 0) {
1337|    return 0;
1338|  }
1339|  switch (c) {
1340|  case '\r':
1341|  case '\n':
1342|    new_inl = handle_newline(subj);
1343|    break;
1344|  case '`':
1345|    new_inl = handle_backticks(subj, options);
1346|    break;
1347|  case '\\':
1348|    new_inl = handle_backslash(subj);
1349|    break;
1350|  case '&':
1351|    new_inl = handle_entity(subj);
1352|    break;
1353|  case '<':
1354|    new_inl = handle_pointy_brace(subj, options);
1355|    break;
1356|  case '*':
1357|  case '_':
1358|  case '\'':
1359|  case '"':
1360|    new_inl = handle_delim(subj, c, (options & CMARK_OPT_SMART) != 0);
1361|    break;
1362|  case '-':
1363|    new_inl = handle_hyphen(subj, (options & CMARK_OPT_SMART) != 0);
1364|    break;
1365|  case '.':
1366|    new_inl = handle_period(subj, (options & CMARK_OPT_SMART) != 0);
1367|    break;
1368|  case '[':
1369|    advance(subj);
1370|    new_inl = make_str(subj, subj->pos - 1, subj->pos - 1, cmark_chunk_literal("["));
1371|    push_bracket(subj, false, new_inl);
1372|    break;
1373|  case ']':
1374|    new_inl = handle_close_bracket(subj);
1375|    break;
1376|  case '!':
1377|    advance(subj);
1378|    if (peek_char(subj) == '[') {
1379|      advance(subj);
1380|      new_inl = make_str(subj, subj->pos - 2, subj->pos - 1, cmark_chunk_literal("!["));
1381|      push_bracket(subj, true, new_inl);
1382|    } else {
1383|      new_inl = make_str(subj, subj->pos - 1, subj->pos - 1, cmark_chunk_literal("!"));
1384|    }
1385|    break;
1386|  default:
1387|    endpos = subject_find_special_char(subj, options);
1388|    contents = cmark_chunk_dup(&subj->input, subj->pos, endpos - subj->pos);
1389|    startpos = subj->pos;
1390|    subj->pos = endpos;
1391|
1392|    // if we're at a newline, strip trailing spaces.
1393|    if (S_is_line_end_char(peek_char(subj))) {
1394|      cmark_chunk_rtrim(&contents);
1395|    }
1396|
1397|    new_inl = make_str(subj, startpos, endpos - 1, contents);
1398|  }
1399|  if (new_inl != NULL) {
1400|    append_child(parent, new_inl);
1401|  }
1402|
1403|  return 1;
