1452|  subject_from_buf(mem, -1, 0, &subj, input, NULL);
1453|
1454|  // parse label:
1455|  if (!link_label(&subj, &lab) || lab.len == 0)
1456|    return 0;
1457|
1458|  // colon:
1459|  if (peek_char(&subj) == ':') {
1460|    advance(&subj);
1461|  } else {
1462|    return 0;
1463|  }
1464|
1465|  // parse link url:
1466|  spnl(&subj);
1467|  if ((matchlen = manual_scan_link_url(&subj.input, subj.pos, &url)) > -1) {
1468|    subj.pos += matchlen;
1469|  } else {
1470|    return 0;
1471|  }
1472|
1473|  // parse optional link_title
1474|  beforetitle = subj.pos;
1475|  spnl(&subj);
1476|  matchlen = subj.pos == beforetitle ? 0 : scan_link_title(&subj.input, subj.pos);
1477|  if (matchlen) {
1478|    title = cmark_chunk_dup(&subj.input, subj.pos, matchlen);
1479|    subj.pos += matchlen;
1480|  } else {
1481|    subj.pos = beforetitle;
1482|    title = cmark_chunk_literal("");
1483|  }
1484|
1485|  // parse final spaces and newline:
1486|  skip_spaces(&subj);
1487|  if (!skip_line_end(&subj)) {
1488|    if (matchlen) { // try rewinding before title
1489|      subj.pos = beforetitle;
1490|      skip_spaces(&subj);
1491|      if (!skip_line_end(&subj)) {
1492|        return 0;
1493|      }
1494|    } else {
1495|      return 0;
1496|    }
1497|  }
1498|  // insert reference into refmap
1499|  cmark_reference_create(refmap, &lab, &url, &title);
