122|static bool is_autolink(cmark_node *node) {
123|  const unsigned char *title;
124|  const unsigned char *url;
125|  cmark_node *link_text;
126|
127|  if (node->type != CMARK_NODE_LINK) {
128|    return false;
129|  }
130|
131|  url = node->as.link.url;
132|  if (url == NULL || _scan_scheme(url) == 0) {
133|    return false;
134|  }
135|
136|  title = node->as.link.title;
137|  // if it has a title, we can't treat it as an autolink:
138|  if (title && title[0]) {
139|    return false;
140|  }
141|
142|  link_text = node->first_child;
143|  if (link_text == NULL) {
144|    return false;
145|  }
146|  cmark_consolidate_text_nodes(link_text);
147|  if (strncmp((const char *)url, "mailto:", 7) == 0) {
148|    url += 7;
149|  }
150|  return link_text->data != NULL &&
151|         strcmp((const char *)url, (char *)link_text->data) == 0;
